const MAX_CONTEXT_CHARS = 4000;

function renderServiceTable(rows) {
  const header = '| service | status | errorRate |\n|---|---|---|';
  const body = rows.map((r) => `| ${r.service} | ${r.status} | ${r.errorRate} |`).join('\n');
  return header + '\n' + body;
}

function assembleInvocationPrompt(task, rows, historyText) {
  const table = renderServiceTable(rows);
  const boundedHistory = historyText.length > MAX_CONTEXT_CHARS
    ? '[compacted: ' + (historyText.length - MAX_CONTEXT_CHARS) + ' chars offloaded]\n' + historyText.slice(-MAX_CONTEXT_CHARS)
    : historyText;
  return `Task: ${task}\n\n${table}\n\nHistory:\n${boundedHistory}`;
}

module.exports = { MAX_CONTEXT_CHARS, renderServiceTable, assembleInvocationPrompt };

